const pageMap=new Map(pages.map(p=>[p.slug,p]));
const familyMap=new Map(families.map(f=>[f.id,f]));
const familyPages=f=>f.children.map(s=>pageMap.get(s)).filter(Boolean);

function ensureCss(html,file){if(html.includes("site-v3-upgrade.css"))return html;return html.replace("</head>",`  <link rel="stylesheet" href="${href(file,cssTarget)}">\n</head>`)}
function replaceMain(html,main){return html.replace(/<main[\s\S]*?<\/main>/,`<main>${main}</main>`)}
function rewriteHead(html,{title,description,canonical,noindex=false}){html=html.replace(/<title>[\s\S]*?<\/title>/,`<title>${esc(title)}</title>`);html=html.replace(/<meta name="description" content="[^"]*">/,`<meta name="description" content="${esc(description)}">`);html=html.replace(/<link rel="canonical" href="[^"]*">/,`<link rel="canonical" href="${esc(canonical)}">`);if(noindex&&!html.includes('name="robots"'))html=html.replace("</head>",'  <meta name="robots" content="noindex,follow">\n</head>');return html}
function specs(rows){return `<div class="v3p-spec-grid">${rows.map(([a,b])=>`<div class="v3p-spec"><span>${esc(a)}</span><strong>${esc(b)}</strong></div>`).join("")}</div>`}
function table(cols,rows){return `<div class="v3p-table-wrap"><table class="v3p-table"><thead><tr>${cols.map(x=>`<th>${esc(x)}</th>`).join("")}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${esc(x)}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`}
function prefabTable(current){return `<div class="v3p-table-wrap"><table class="v3p-table"><thead><tr><th>Series</th><th>Transformer</th><th>HV</th><th>LV</th><th>Capacity</th><th>Frequency</th><th>Protection</th><th>Max. weight</th></tr></thead><tbody>${prefab.map(r=>`<tr class="${r.id===current?"highlight":""}"><td>${r.series}</td><td>${r.transformer}</td><td>${r.hv}</td><td>${r.lv}</td><td>${r.capacity}</td><td>${r.frequency}</td><td>${r.protection}</td><td>${r.weight}</td></tr>`).join("")}</tbody></table></div>`}
function mediaClass(src){if(/case-|renewable-projects|factory-campus|offshore/i.test(src))return"cover";if(/ga-|drawing/i.test(src))return"drawing";return""}
function gallery(p,file){return `<div class="v3p-gallery">${p.gallery.slice(0,3).map((src,i)=>`<figure class="v3p-photo ${mediaClass(src)}"><img src="${media(file,src)}" alt="${esc(p.title)} ${i+1}" loading="lazy"></figure>`).join("")}</div>`}
function familyNav(f,current){return `<nav class="v3p-family-nav">${familyPages(f).map(p=>`<a class="${p.slug===current?"current":""}" href="../${p.slug}/">${esc(p.title.replace(/ Transformer$| Substation$/g,""))}</a>`).join("")}</nav>`}
function productMain(p,file){const f=familyMap.get(p.family);const rangeTable=p.comparison?prefabTable(p.comparison):table(p.columns,p.rows);return `<section class="v3p-hero"><div class="v3p-hero-copy"><div class="v3p-breadcrumb"><a href="../../products.html">Products</a><span>/</span><a href="../${f.landing}/">${f.title}</a><span>/</span><span>${p.title}</span></div><p class="v3p-kicker">${p.kicker}</p><h1>${p.title}</h1><p>${p.summary}</p><div class="v3p-hero-proof"><span>${p.voltage}</span><span>${p.range}</span><span>Catalog product range</span></div>${familyNav(f,p.slug)}</div><div class="v3p-hero-media"><img src="${media(file,p.image)}" alt="${p.title}"></div></section><section class="v3p-section"><div class="v3p-shell"><p class="v3p-kicker">Technical Range</p><h2 class="v3p-title">Select by voltage class and rating range</h2><p class="v3p-lead">The technical range below follows Tianyu's current product catalog. Product selection starts from voltage class, capacity ladder and application. Certificates and test reports are available separately in Resources.</p>${specs(p.specs)}<h3 style="margin-top:34px">Published rating ladder</h3>${rangeTable}<p class="v3p-mini-note">Catalog performance values are reference data. Final guaranteed values, interfaces and overall dimensions are confirmed in the approved technical specification and drawings for the order.</p></div></section><section class="v3p-section v3p-soft"><div class="v3p-shell v3p-two-col"><div><p class="v3p-kicker">Application</p><h2>Typical application areas</h2><ul class="v3p-list">${p.applications.map(x=>`<li>${x}</li>`).join("")}</ul></div><div><p class="v3p-kicker">Engineering Characteristics</p><h2>Platform features</h2><ul class="v3p-list">${p.features.map(x=>`<li>${x}</li>`).join("")}</ul></div></div></section><section class="v3p-section"><div class="v3p-shell"><p class="v3p-kicker">Product & Engineering Views</p><h2 class="v3p-title">Product images stay uncropped; project photography gets the wide frame</h2>${gallery(p,file)}<div class="v3p-source"><strong>Content source:</strong> ${p.source}</div></div></section><section class="v3p-cta"><div><p class="v3p-kicker">Technical Inquiry</p><h2>Send the project ratings for engineering review</h2><p>Capacity, HV/LV voltage, frequency, vector group, impedance, tap range, site conditions, standards and required delivery help engineering review the right platform.</p></div><div class="v3p-cta-actions"><button class="btn btn-primary" type="button" data-quote-open>Request a Technical Review</button><a class="v3p-outline" href="../../resources.html">Certificates & Reports</a></div></section>`}
function familyMain(f,file){const kids=familyPages(f);return `<section class="v3p-family-hero"><div class="v3p-family-hero-copy"><div class="v3p-breadcrumb"><a href="../../products.html">Products</a><span>/</span><span>${f.title}</span></div><p class="v3p-kicker">Product Family</p><h1>${f.title}</h1><p class="v3p-lead">${f.subtitle}. Choose a voltage or application platform first, then use the dedicated page's rating table for technical selection.</p></div><div class="v3p-family-hero-media"><img src="${media(file,f.image)}" alt="${f.title}"></div></section><section class="v3p-section"><div class="v3p-shell"><p class="v3p-kicker">Product Range</p><h2 class="v3p-title">Choose the platform first</h2><div class="v3p-platform-grid">${kids.map(p=>`<a class="v3p-platform-card" href="../${p.slug}/"><div class="media"><img src="${media(file,p.image)}" alt="${p.title}" loading="lazy"></div><div class="copy"><p class="v3p-kicker">${p.kicker}</p><h3>${p.title}</h3><span class="range">${p.range}</span><small>${p.voltage}</small></div></a>`).join("")}</div></div></section><section class="v3p-section v3p-soft"><div class="v3p-shell"><p class="v3p-kicker">Selection Logic</p><h2 class="v3p-title">Voltage class → capacity → electrical requirements → project options</h2><p class="v3p-lead">Every platform page uses the same structure so procurement and engineering teams can compare products without learning a new layout each time.</p></div></section><section class="v3p-cta"><div><p class="v3p-kicker">Project Inquiry</p><h2>Not sure which range fits?</h2><p>Send the electrical system and application. The technical inquiry includes a quick path plus optional detailed engineering fields.</p></div><button class="btn btn-primary" type="button" data-quote-open>Request a Technical Review</button></section>`}
function productCard(p,file){return `<a class="v3p-platform-card" href="products/${p.slug}/"><div class="media"><img src="${media(file,p.image)}" alt="${p.title}" loading="lazy"></div><div class="copy"><p class="v3p-kicker">${familyMap.get(p.family).title}</p><h3>${p.title}</h3><span class="range">${p.range}</span><small>${p.voltage}</small></div></a>`}
function productsMain(file){return `<section class="v3p-index-hero"><div class="copy"><p class="v3p-kicker">Product Portfolio</p><h1>Find the transformer by voltage, capacity and application.</h1><p class="v3p-lead">Start from a product family, then open the voltage or application platform that matches the project. Each platform page follows the same technical-selection structure.</p><div class="v3p-range-strip"><a href="products/12kv-oil-immersed-distribution-transformer/">≤12 kV</a><a href="products/35kv-power-transformer/">35 kV</a><a href="products/40-5kv-renewable-oil-immersed-transformer/">40.5 kV</a><a href="products/66kv-power-transformer/">66 kV</a><a href="products/110kv-power-transformer/">110 kV</a><span>132 kV project references</span><a href="products/220kv-power-transformer/">220 kV</a></div></div><div class="media"><img src="${media(file,"evidence/sample-photo-pages/power-transformer-240mva-220kv-ssz22-sample-photo-page.webp")}" alt="Tianyu power transformer"></div></section><section class="v3p-section"><div class="v3p-shell"><p class="v3p-kicker">Browse by Product Family</p><h2 class="v3p-title">Five clear routes into the portfolio</h2><div class="v3p-family-grid">${families.map(f=>`<a class="v3p-family-card" href="products/${f.landing}/"><div class="v3p-family-card-media"><img src="${media(file,f.image)}" alt="${f.title}" loading="lazy"></div><div class="v3p-family-card-copy"><p class="v3p-kicker">Product Family</p><h3>${f.title}</h3><p>${f.subtitle}</p><strong>VIEW RANGE →</strong></div></a>`).join("")}</div></div></section><section class="v3p-section v3p-soft"><div class="v3p-shell"><p class="v3p-kicker">All Product Platforms</p><h2 class="v3p-title">Standalone pages for every catalog platform</h2><div class="v3p-platform-grid">${pages.map(p=>productCard(p,file)).join("")}</div></div></section><section class="v3p-cta"><div><p class="v3p-kicker">Engineering Inquiry</p><h2>Have a specification or single-line diagram?</h2><p>Upload it with the technical inquiry. Detailed electrical, site, standards, loss and delivery fields are available without cluttering the first step.</p></div><button class="btn btn-primary" type="button" data-quote-open>Start Technical Inquiry</button></section>`}
function homeProducts(file){return `<section class="v3p-section v3p-products-home" id="products"><div class="v3p-shell"><p class="v3p-kicker">Products</p><h2 class="v3p-title">Browse by engineering family</h2><div class="v3p-family-grid">${families.map(f=>`<a class="v3p-family-card" href="products/${f.landing}/"><div class="v3p-family-card-media"><img src="${media(file,f.image)}" alt="${f.title}" loading="lazy"></div><div class="v3p-family-card-copy"><p class="v3p-kicker">Product Family</p><h3>${f.title}</h3><p>${f.subtitle}</p><strong>EXPLORE RANGE →</strong></div></a>`).join("")}</div><div class="v3p-range-strip"><a href="products/35kv-power-transformer/">35 kV Power</a><a href="products/66kv-power-transformer/">66 kV Power</a><a href="products/110kv-power-transformer/">110 kV Power</a><a href="products/220kv-power-transformer/">220 kV Power</a><a href="products/12kv-oil-immersed-distribution-transformer/">12 kV Distribution</a><a href="products/40-5kv-new-energy-dry-type-transformer/">40.5 kV Dry-Type</a><a href="products/prefabricated-substations/">Substations</a></div></div></section>`}
function manufacturingMain(file){return `<section class="page-image-hero"><img src="${media(file,"company/factory-campus-panorama.jpeg")}" alt="Tianyu Electric manufacturing base"><div><p class="eyebrow">Manufacturing</p><h1>Transformer Manufacturing & Testing</h1><p>Official factory scale, production systems and transformer manufacturing workflow.</p></div></section><section class="v3p-section"><div class="v3p-shell"><p class="v3p-kicker">Factory at a Glance</p><h2 class="v3p-title">A manufacturing base built around transformers, substations and primary equipment</h2><div class="v3p-company-stats"><div><span>Total investment</span><strong>≈ RMB 250m</strong></div><div><span>Plant area</span><strong>85,243 m²</strong></div><div><span>Large mechanical equipment</span><strong>460</strong></div><div><span>Supporting test equipment</span><strong>60 types</strong></div></div><div class="v3p-company-stats"><div><span>Large main transformers</span><strong>1,200 / yr</strong></div><div><span>Distribution transformers</span><strong>12,000 / yr</strong></div><div><span>Box-type substations</span><strong>10,000 / yr</strong></div><div><span>Complete switchgear</span><strong>15,000 / yr</strong></div></div><p class="v3p-mini-note">Company-scale figures follow the Chinese corporate catalog, which is the selected website source where catalog editions conflict.</p></div></section><section class="v3p-section v3p-soft"><div class="v3p-shell"><p class="v3p-kicker">Digital Manufacturing</p><h2 class="v3p-title">Four intelligent systems across supply, production, quality and logistics</h2><div class="v3p-system-grid"><article><strong>SRM</strong><h3>Efficient Supply Chain System</h3><p>Supplier and material-delivery collaboration.</p></article><article><strong>MOM</strong><h3>Digital Production Management System</h3><p>Production management and process coordination.</p></article><article><strong>QMS</strong><h3>Full-Process Quality Management</h3><p>Quality traceability through the production process.</p></article><article><strong>WMS</strong><h3>Intelligent Logistics System</h3><p>Warehouse and material-flow management.</p></article></div></div></section><section class="v3p-section"><div class="v3p-shell"><p class="v3p-kicker">Transformer Manufacturing</p><h2 class="v3p-title">Core → winding → insulation → active part → drying → tank & final assembly</h2><div class="v3p-platform-grid">${[["Core Processing","Magnetic-core cutting, stacking and assembly."],["Coil Winding","HV and LV coil winding for the selected conductor and insulation system."],["Insulation & Active Part","Insulation assembly, lead work and active-part integration."],["Vacuum Drying","Insulation drying before oil filling and final assembly."],["Tank & Final Assembly","Tank fabrication, accessories and final transformer integration."],["Inspection & Testing","Routine and project-specified testing before release."]].map(([a,b])=>`<article class="v3p-platform-card" style="grid-template-rows:auto"><div class="copy"><p class="v3p-kicker">Manufacturing Stage</p><h3>${a}</h3><p>${b}</p></div></article>`).join("")}</div><div class="v3p-manufacturing-media"><figure><img src="${media(file,"catalog-v3/manufacturing-overview.webp")}" alt="Transformer manufacturing overview"><figcaption>Manufacturing overview. Composite production imagery is kept as one wide visual rather than repeated across process cards.</figcaption></figure><figure><img src="${media(file,"catalog-v3/testing-220kv-lab.webp")}" alt="Transformer test laboratory"><figcaption>Transformer test and inspection capability.</figcaption></figure></div></div></section><section class="v3p-cta"><div><p class="v3p-kicker">Factory & Quality Review</p><h2>Need manufacturing documents for a tender?</h2><p>Use the inquiry form to specify inspection, FAT, witness, documentation and delivery requirements.</p></div><button class="btn btn-primary" data-quote-open>Request Technical Review</button></section>`}
function aboutMain(file){return `<section class="page-image-hero"><img src="${media(file,"company/factory-campus-panorama.jpeg")}" alt="Tianyu Electric factory campus"><div><p class="eyebrow">About Tianyu</p><h1>Electrical manufacturing heritage, modern transformer capability.</h1><p>Fuzhou Tianyu Electric Co., Ltd. is a wholly-owned subsidiary of XJ Group Corporation under China Electrical Equipment Group Co., Ltd.</p></div></section><section class="v3p-section"><div class="v3p-shell v3p-two-col"><div><p class="v3p-kicker">Company Overview</p><h2 class="v3p-title">Established in 1996. Built on a longer electrical-manufacturing heritage.</h2></div><div><p class="v3p-lead">Tianyu Electric was formed in 1996 from predecessor electrical-equipment factories. It is a southern manufacturing base for primary electrical equipment under China Electrical Equipment Group.</p></div></div><div class="v3p-shell"><div class="v3p-company-stats"><div><span>Established</span><strong>1996</strong></div><div><span>Product series</span><strong>30+</strong></div><div><span>Plant area</span><strong>85,243 m²</strong></div><div><span>Large mechanical equipment</span><strong>460</strong></div></div></div></section><section class="v3p-section v3p-soft"><div class="v3p-shell"><p class="v3p-kicker">Development</p><h2 class="v3p-title">A concise company timeline</h2><div class="v3p-timeline"><article><strong>1996</strong><p>Tianyu Electric established through the combination of predecessor electrical-equipment factories.</p></article><article><strong>2016</strong><p>The new Tianyu factory area was completed and entered production.</p></article><article><strong>2021</strong><p>XJ Group became part of China Electrical Equipment Group.</p></article><article><strong>Today</strong><p>Transformer, prefabricated-substation, switchgear and primary-equipment manufacturing for utility, renewable, industrial and infrastructure projects.</p></article></div></div></section><section class="v3p-cta"><div><p class="v3p-kicker">Explore Capability</p><h2>See how the products are manufactured and tested.</h2></div><a class="v3p-outline" href="manufacturing.html">Manufacturing & Testing</a></section>`}
function appTaxonomy(){const items=[["Power Grid & Utility","Substations · transmission · distribution"],["Renewable Energy","Wind · offshore wind · solar"],["Energy Storage","BESS · compressed-air storage"],["Industrial & Mining","Cement · metallurgy · chemical · mining"],["Data Centers & Critical Loads","Data center · critical infrastructure"],["Transportation","Metro · rail · airport · highway"],["Water & Hydropower","Hydropower · pumping · water diversion"],["Commercial & Municipal","Buildings · municipal · landmark projects"]];return `<section class="v3p-section v3p-soft"><div class="v3p-shell"><p class="v3p-kicker">Application Sectors</p><h2 class="v3p-title">Browse experience by the way customers buy power equipment</h2><div class="v3p-application-grid">${items.map(([a,b])=>`<article><h3>${a}</h3><p>${b}</p></article>`).join("")}</div></div></section>`}
function quoteForm(compact=false){return `<form class="quote-form${compact?" compact":""}"><label>Name<input name="name" autocomplete="name" required></label><label>Email<input name="email" type="email" autocomplete="email" required></label><label>Company<input name="company" autocomplete="organization"></label><label>Destination Country<input name="country" autocomplete="country-name"></label><label>Product Family<select name="product"><option value="">Select a product family</option>${families.map(f=>`<option>${f.title}</option>`).join("")}</select></label><label>Capacity / Voltage<input name="rating" placeholder="e.g. 63 MVA, 110/37/10.5 kV"></label><label>Quantity<input name="quantity" placeholder="e.g. 2 units"></label><label>Required Delivery<input name="requiredDelivery" placeholder="Required date or project window"></label><details class="v3p-rfq-details"><summary>Add Technical Details</summary><div class="v3p-rfq-grid"><label>Rated Power<input name="ratedPower" placeholder="kVA / MVA"></label><label>HV Voltage<input name="hvVoltage" placeholder="kV"></label><label>LV / MV Voltage<input name="lvVoltage" placeholder="kV / V"></label><label>Frequency<select name="frequency"><option value="">Select</option><option>50 Hz</option><option>60 Hz</option></select></label><label>Vector Group<input name="vectorGroup" placeholder="e.g. Dyn11 / YNyn0d11"></label><label>Impedance<input name="impedance" placeholder="% or project requirement"></label><label>Tap Range<input name="tapRange" placeholder="e.g. ±8×1.25%"></label><label>Tap Changer<select name="tapChanger"><option value="">Select</option><option>OLTC</option><option>OCTC / off-circuit</option><option>Not specified</option></select></label><label>Cooling<input name="cooling" placeholder="e.g. ONAN / ONAF / AN / AF"></label><label>Installation<select name="installation"><option value="">Select</option><option>Outdoor</option><option>Indoor</option></select></label><label>Altitude<input name="altitude" placeholder="m above sea level"></label><label>Ambient Temperature<input name="ambient" placeholder="max / min °C"></label><label>Applicable Standard<input name="requiredStandard" placeholder="IEC / EN / utility specification"></label><label>Loss / Efficiency Requirement<input name="efficiency" placeholder="If applicable"></label><label>Enclosure / IP<input name="enclosure" placeholder="If applicable"></label><label>Winding Material<input name="windingMaterial" placeholder="Copper / aluminum / specification"></label><label class="full">Accessories & Monitoring<textarea name="accessories" rows="3" placeholder="Protection, monitoring, CTs, gauges, interfaces..."></textarea></label><label class="full">Site Conditions<textarea name="siteConditions" rows="3" placeholder="Corrosion, seismic, marine, dust, humidity, harmonics..."></textarea></label><label class="full">Project Requirements<textarea name="message" rows="5" placeholder="Application, project stage, standards, special guarantees and document requirements"></textarea></label><label class="full">Technical File<input name="file" type="file" accept=".pdf,.doc,.docx,.xls,.xlsx,.dwg,.dxf,.jpg,.jpeg,.png"></label><p class="v3p-rfq-help">Helpful attachments: single-line diagram, transformer specification, tender document, load profile, harmonic spectrum, site layout and cable-interface information.</p></div></details><button class="btn btn-primary" type="submit">Send Inquiry</button><p class="form-message" aria-live="polite"></p></form>`}
function upgradeForms(html){return html.replace(/<form class="quote-form([^>]*)>[\s\S]*?<\/form>/g,(m,attrs)=>quoteForm(/compact/.test(attrs)))}
function productMenu(from){const links=families.map(f=>`<a href="${href(from,path.join(dist,"products",f.landing,"index.html"))}">${f.title}</a>`).join("");return links+`<a href="${href(from,path.join(dist,"products.html"))}#all-platforms">All Product Platforms</a>`}
function navAndForms(){const walk=d=>{for(const e of fs.readdirSync(d,{withFileTypes:true})){const f=path.join(d,e.name);if(e.isDirectory())walk(f);else if(e.isFile()&&e.name.endsWith(".html")&&e.name!=="catalog.html"){let h=read(f);if(!h)continue;h=h.replace(/(<div class="nav-item nav-dropdown"><a[^>]*>Products<\/a><div class="dropdown-menu">)[\s\S]*?(<\/div><\/div>)/,`$1${productMenu(f)}$2`);h=upgradeForms(h);h=ensureCss(h,f);write(f,h)}}};walk(dist)}
function template(){return read(path.join(dist,"products","high-voltage-power-transformer","index.html"))||read(path.join(dist,"products","oil-immersed-distribution-transformer","index.html"))}
function buildProducts(){const t=template();if(!t)throw new Error("Product template missing");const index=path.join(dist,"products.html");let h=read(index);h=rewriteHead(h,{title:"Transformer Product Range | Tianyu Electric",description:"Browse Tianyu transformers and prefabricated substations by voltage class, capacity range and application.",canonical:"/products.html"});h=replaceMain(h,productsMain(index));write(index,ensureCss(h,index));for(const f of families){const file=path.join(dist,"products",f.landing,"index.html");let x=rewriteHead(t,{title:`${f.title} | Tianyu Electric`,description:f.subtitle,canonical:`/products/${f.landing}/`});x=replaceMain(x,familyMain(f,file));write(file,ensureCss(x,file))}for(const p of pages){const file=path.join(dist,"products",p.slug,"index.html");let x=rewriteHead(t,{title:`${p.title} | Tianyu Electric`,description:p.summary,canonical:`/products/${p.slug}/`});x=replaceMain(x,productMain(p,file));write(file,ensureCss(x,file))}}
function legacyAliases(){for(const [oldSlug,newSlug] of [["dry-type-prefabricated-substation","yb-prefabricated-substation"],["oil-immersed-prefabricated-substation","ybh-prefabricated-substation"],["american-type-combined-transformer","zgs-prefabricated-substation"]]){const file=path.join(dist,"products",oldSlug,"index.html");if(!fs.existsSync(file))continue;const p=pageMap.get(newSlug);let h=read(file);h=rewriteHead(h,{title:`${p.title} | Tianyu Electric`,description:p.summary,canonical:`/products/${newSlug}/`});h=replaceMain(h,productMain(p,file));write(file,ensureCss(h,file))}}
function neutralizeModels(){for(const rootName of ["high-voltage-power-transformer","oil-immersed-distribution-transformer","cast-resin-dry-type-transformer","dry-type-prefabricated-substation","oil-immersed-prefabricated-substation","american-type-combined-transformer"]){const dir=path.join(dist,"products",rootName);if(!fs.existsSync(dir))continue;for(const e of fs.readdirSync(dir,{withFileTypes:true})){if(!e.isFile()||e.name==="index.html"||!e.name.endsWith(".html"))continue;const file=path.join(dir,e.name);let h=read(file);h=rewriteHead(h,{title:"Technical Evidence Reference | Tianyu Electric",description:"Legacy evidence URL retained for compatibility. Product selection is organized by product range.",canonical:"/products.html",noindex:true});h=replaceMain(h,`<section class="v3p-legacy-note"><div><p class="v3p-kicker">Legacy Evidence URL</p><h1>Product selection has moved to the product range.</h1><p>This URL is retained for older links. Certificate and test-report model numbers remain available in the evidence library, while product selection now starts from voltage class and rating range.</p><div class="actions"><a href="${href(file,path.join(dist,"products.html"))}">Browse Product Ranges</a><a href="${href(file,path.join(dist,"resources.html"))}">Certificates & Test Reports</a></div></div></section>`);write(file,ensureCss(h,file))}}}
function upgradeHome(){const file=path.join(dist,"index.html");let h=read(file);if(!h)return;h=h.replace(/<section class="section yw-one-stop" id="products">[\s\S]*?<\/section>/,homeProducts(file));h=h.replace(/<div class="yw-company-copy">([\s\S]*?)<p>Wholly-owned subsidiary of XJ Group Corporation under China Electrical Equipment Group Co\., Ltd\. A southern manufacturing base for primary electrical equipment of China Electrical Equipment Group Co\., Ltd\.<\/p>([\s\S]*?)<\/div>/,`<div class="yw-company-copy">$1$2</div>`);h=h.replace(/<div class="yw-stat-grid">[\s\S]*?<\/div>\s*<\/section>/,`<div class="yw-stat-grid"><article><small>01</small><strong>220 kV</strong><span>Transformer Platform</span></article><article><small>02</small><strong>30+</strong><span>Product Series</span></article><article><small>03</small><strong>85,243 m²</strong><span>Plant Area</span></article><article><small>04</small><strong>460</strong><span>Large Mechanical Equipment</span></article></div></section>`);h=h.replace("Independent certificates and model-specific reports organized by exact tested model.","Independent certificates and test reports organized for procurement and engineering review.");write(file,ensureCss(h,file))}
function upgradePages(){for(const [name,title,description,main] of [["manufacturing.html","Transformer Manufacturing & Testing | Tianyu Electric","Tianyu transformer manufacturing scale, production systems and testing capability.",manufacturingMain],["about.html","About Tianyu Electric | Transformer Manufacturer","Fuzhou Tianyu Electric company background and transformer manufacturing capability.",aboutMain]]){const file=path.join(dist,name);let h=read(file);if(!h)continue;h=rewriteHead(h,{title,description,canonical:`/${name}`});h=replaceMain(h,main(file));write(file,ensureCss(h,file))}const app=path.join(dist,"applications.html");let h=read(app);if(h){h=h.replace(/https:\/\/images\.unsplash\.com\/[^'"\)]+/g,media(app,"applications/renewable-wind-solar-landscape.jpeg"));h=h.replace(/<main>/,"<main>"+appTaxonomy());write(app,ensureCss(h,app))}}
function semanticImages(){const map={"products.html":"evidence/sample-photo-pages/power-transformer-240mva-220kv-ssz22-sample-photo-page.webp","applications.html":"applications/renewable-wind-solar-landscape.jpeg","resources.html":"catalog-v3/testing-220kv-lab.webp","about.html":"company/factory-campus-panorama.jpeg","manufacturing.html":"company/factory-campus-panorama.jpeg","news.html":"company/factory-campus-panorama.jpeg"};for(const [name,src] of Object.entries(map)){const file=path.join(dist,name);let h=read(file);if(!h)continue;h=h.replace(/https:\/\/images\.unsplash\.com\/[^'"\)]+/g,media(file,src));write(file,h)}}
function artifact(){write(path.join(dist,"product-range-pages.json"),JSON.stringify({families,pages:pages.map(p=>({slug:p.slug,family:p.family,title:p.title,range:p.range,voltage:p.voltage,source:p.source}))},null,2)+"\n")}
function validate(){const checks=[["products.html","Standalone pages for every catalog platform"],["products/35kv-power-transformer/index.html","8–31.5 MVA"],["products/66kv-power-transformer/index.html","6.3–63 MVA"],["products/110kv-power-transformer/index.html","SSZ-6300~63000/110"],["products/220kv-power-transformer/index.html","31.5–240 MVA"],["products/zgs-prefabricated-substation/index.html","200–40,000 kVA"],["manufacturing.html","85,243 m²"],["manufacturing.html","MOM"],["index.html","Power Transformers"],["index.html","85,243 m²"]];for(const [f,s] of checks){if(!read(path.join(dist,f)).includes(s))throw new Error(`V3 validation: ${f} missing ${s}`)}for(const p of pages){for(const src of [p.image,...p.gallery]){if(!fs.existsSync(path.join(dist,"assets","media",src)))throw new Error(`V3 validation: missing media ${src}`)}}const legacy=path.join(dist,"products","high-voltage-power-transformer","sz22-50000-110-nx1.html");if(fs.existsSync(legacy)&&!read(legacy).includes('name="robots" content="noindex'))throw new Error("V3 validation: legacy exact-model URL remains a marketing page");const products=read(path.join(dist,"products.html"));if(/Separate published capability from proven evidence|exact third-party tested models/i.test(products))throw new Error("V3 validation: old evidence-layer architecture still visible")}
function main(){if(!fs.existsSync(dist))throw new Error("dist missing");fs.mkdirSync(path.dirname(cssTarget),{recursive:true});fs.copyFileSync(cssSource,cssTarget);buildProducts();legacyAliases();neutralizeModels();upgradeHome();upgradePages();semanticImages();navAndForms();artifact();validate();console.log(`Website V3 generated ${families.length} product families and ${pages.length} standalone catalog-platform pages.`)}
main();
